import Foundation

public enum PrivacyFilter {
    public static let defaultExcludedApps = [
        "com.1password.1password", "com.agilebits.onepassword7", "com.agilebits.onepassword-osx",
        "com.bitwarden.desktop", "org.keepassxc.keepassxc", "com.apple.Passwords",
    ]
    public static func hasPrivateMarker(_ types: [String]) -> Bool {
        let markers: Set<String> = [
            "org.nspasteboard.TransientType", "org.nspasteboard.ConcealedType",
            "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword",
        ]
        return !markers.isDisjoint(with: types)
    }
    public static func looksSensitive(_ text: String) -> Bool {
        let patterns = [
            #"-----BEGIN (?:RSA |EC |OPENSSH |DSA )?PRIVATE KEY-----"#,
            #"\b(?:AKIA|ASIA)[A-Z0-9]{16}\b"#,
            #"\b(?:sk-[A-Za-z0-9_-]{20,}|gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})\b"#,
            #"\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\b"#,
            #"(?i)\b(?:password|passwd|api[_-]?key|access[_-]?token|client[_-]?secret)\s*[:=]\s*\S+"#,
            #"^\s*\d{4,8}\s*$"#,
        ]
        return patterns.contains { text.range(of: $0, options: .regularExpression) != nil }
    }
}
